package ratelimiter

import (
    "context"
    "errors"
    "sync"
    "time"
)

type Clock interface {
    Now() time.Time
}

type Config struct {
    Capacity        int
    RefillPerSecond float64
}

type Dependencies struct {
    Clock Clock
}

type Limiter struct {
    mu          sync.Mutex
    config      Config
    clock       Clock
    tokens      float64
    lastRefill  time.Time
}

func New(configuration Config, dependencies Dependencies) (*Limiter, error) {
    if configuration.Capacity <= 0 {
        return nil, errors.New("capacity must be positive")
    }
    if configuration.RefillPerSecond < 0 {
        return nil, errors.New("refill rate must be non-negative")
    }

    clock := dependencies.Clock
    if clock == nil {
        clock = &systemClock{}
    }

    now := clock.Now()

    return &Limiter{
        config:     configuration,
        clock:      clock,
        tokens:     float64(configuration.Capacity),
        lastRefill: now,
    }, nil
}

type systemClock struct{}

func (s *systemClock) Now() time.Time {
    return time.Now()
}

func (l *Limiter) Allow(ctx context.Context, tokens int) (bool, error) {
    if tokens <= 0 {
        return false, errors.New("tokens must be positive")
    }

    select {
    case <-ctx.Done():
        return false, ctx.Err()
    default:
    }

    l.mu.Lock()
    defer l.mu.Unlock()

    // Refill bucket based on elapsed time
    now := l.clock.Now()
    elapsed := now.Sub(l.lastRefill)
    l.lastRefill = now

    added := elapsed.Seconds() * l.config.RefillPerSecond
    l.tokens += added
    if l.tokens > float64(l.config.Capacity) {
        l.tokens = float64(l.config.Capacity)
    }

    // Check if we have enough tokens
    if l.tokens >= float64(tokens) {
        l.tokens -= float64(tokens)
        return true, nil
    }

    return false, nil
}
